window.RP_SESSION={"id":"S-e35f6d81f692","messages":[{"id":"RP-II-0033243","time":"2026-02-11T20:22:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"음... 그러니까.. 이걸.. 이렇게... 깎아서.... 이걸 끈적이는 나무 진액으로 붙히면...","characters":["P-d2afca5de258"]},{"id":"RP-II-0033244","time":"2026-02-11T20:23:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"데스티나는 불이 피워지지 않은 모닥불 곁에 앉아 한개의 나무조각을 단도로 깎고 있었다.","characters":["P-d2afca5de258"]},{"id":"RP-II-0033245","time":"2026-02-11T20:23:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"이것을 하는 이유에 대해서 묻는사람이 있다면 아마도 그냥이라고 답할만한 쓸모 없는 일이었지만","characters":["P-d2afca5de258"]},{"id":"RP-II-0033246","time":"2026-02-11T20:24:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"그냥, 성취감이 있기에 하는 것도 있고.. 심심하면 뭐든지 하고 싶어진다는게 이거인가 싶다","characters":["P-d2afca5de258"]},{"id":"RP-II-0033247","time":"2026-02-11T20:26:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"지금은, 검을 들고 있는 자신을 조각하고 있는 것 같다. 극도의 집중력이 요하는 건지, 아니면 자신이 실력이 부족한건지. 누가 수다를 떨면서 다가와도 눈치채지 못할 것같다","characters":["P-d2afca5de258"]},{"id":"RP-II-0033248","time":"2026-02-11T20:27:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"\" 아! \"\n\n자신의 단도가 그 나무조각을 생각했던것보다 더 많이 깎아 버리자, 그것을 다시 모닥불 안에 넣어두더니, 모닥불에 있던 나무 하나를 다시 꺼내 크기에 맞게 등분하기 시작했다.","characters":["P-d2afca5de258"]},{"id":"RP-II-0033249","time":"2026-02-11T20:29:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"오늘도 평화로운 데스티나의 취미생활이었다.","characters":["P-d2afca5de258"]},{"id":"RP-II-0033250","time":"2026-02-11T20:29:00+09:00","room":"RP II","name":"데스티나","profile":"지헬 루티크","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d2afca5de258"]},{"id":"RP-II-0033251","time":"2026-02-11T20:30:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
